        <div><b>${count ? t.name : 'Undiscovered'}</b><small>${r.label} · ${t.value} coins</small>${count ? `<p>${t.lore}</p>` : '<p>The forest keeps this one hidden.</p>'}</div>
        <div class="count">${count}</div>
