#hint-bar.fade { opacity: 0; }
#hint-bar kbd { font-size: 8px; }
#reticle { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; border-radius: 50%; background: rgba(255,240,200,0.5); transform: translate(-50%,-50%); opacity: 0.6; box-shadow: 0 0 6px rgba(255,240,200,0.5); }

#ability-hint {
  position: absolute; bottom: calc(90px + var(--safe-bottom)); left: 50%; transform: translateX(-50%);
  padding: 6px 14px; border-radius: 999px; background: rgba(15,20,11,0.8); border: 1px solid rgba(255,120,80,0.35);
  color: #ffb48e; font-size: 9px; letter-spacing: 0.16em; text-transform: uppercase;
}

/* ---------- Pause / Den ---------- */
#pause-screen {
  z-index: 40;
  background: radial-gradient(ellipse at 50% 40%, rgba(18,24,14,0.4), rgba(7,10,5,0.82));
  backdrop-filter: blur(12px) saturate(0.8);
  animation: fadein 0.25s ease both;
}
@keyframes fadein { from { opacity: 0; } }
.pause-inner {
  width: min(1120px, 94vw); height: min(790px, 88vh);
  display: flex; flex-direction: column;
  background: linear-gradient(160deg, rgba(27,35,21,0.96), rgba(13,18,10,0.98));
  border: 1px solid rgba(217,181,103,0.25);
  box-shadow: 0 40px 120px rgba(0,0,0,0.65), 0 1px 0 rgba(255,255,255,0.06) inset;
  border-radius: 12px; overflow: hidden;
  animation: panin 0.35s cubic-bezier(0.2,0.7,0.2,1) both;
}
@keyframes panin { from { opacity: 0; transform: scale(0.985) translateY(10px); } }
.pause-head {
  display: flex; align-items: center; gap: 22px; padding: 20px 26px 15px;
  border-bottom: 1px solid rgba(232,213,170,0.12);
}
.pause-title small { display: block; font-size: 8px; letter-spacing: 0.3em; color: var(--gold); }
.pause-title h2 { font-family: var(--serif); font-size: 32px; font-weight: 400; letter-spacing: 0.04em; color: #f4e8c9; line-height: 1; margin-top: 3px; }
.pause-res { margin-left: auto; display: flex; gap: 18px; font-size: 11px; color: var(--cream-dim); }
.pause-res b { color: #f1e5c5; }
.tabs {
  display: flex; gap: 2px; padding: 0 22px; border-bottom: 1px solid rgba(232,213,170,0.12);
  overflow-x: auto; scrollbar-width: none;
}
.tabs::-webkit-scrollbar { display: none; }
.tabs button {
  position: relative; padding: 13px 17px; font-size: 10px; font-weight: 700; letter-spacing: 0.16em;
  text-transform: uppercase; color: var(--cream-dim); white-space: nowrap;
  border-bottom: 2px solid transparent; transition: color 0.15s, border-color 0.15s;
}
.tabs button:hover { color: var(--cream); }
.tabs button.active { color: var(--gold-bright); border-bottom-color: var(--gold); }
.tabs .dot { display: inline-block; width: 5px; height: 5px; border-radius: 50%; background: #d35b39; vertical-align: middle; margin-left: 4px; box-shadow: 0 0 8px rgba(211,91,57,0.8); }
.menu-content { flex: 1; overflow-y: auto; padding: 24px 26px 30px; scrollbar-width: thin; scrollbar-color: rgba(217,181,103,0.3) transparent; }
.menu-content::-webkit-scrollbar { width: 8px; }
.menu-content::-webkit-scrollbar-thumb { background: rgba(217,181,103,0.22); border-radius: 4px; }
.pause-foot { display: flex; justify-content: space-between; padding: 10px 26px; font-size: 9px; color: rgba(205,191,158,0.65); border-top: 1px solid rgba(232,213,170,0.1); letter-spacing: 0.06em; }
#save-dot { display: inline-block; width: 5px; height: 5px; border-radius: 50%; background: #8fb45c; box-shadow: 0 0 8px rgba(143,180,92,0.7); vertical-align: middle; }

/* Menu shared */
.menu-section-title { font-family: var(--serif); font-size: 20px; color: #f2e6c7; font-weight: 400; margin-bottom: 4px; }
.menu-section-sub { font-size: 10px; color: var(--cream-dim); margin-bottom: 18px; letter-spacing: 0.04em; }
.panel-grid { display: grid; grid-template-columns: 1.25fr 0.75fr; gap: 18px; }
.card {
  background: linear-gradient(160deg, rgba(255,255,255,0.045), rgba(255,255,255,0.018));
  border: 1px solid rgba(232,213,170,0.14); border-radius: 9px; padding: 16px 18px;
}
.card h3 { font-family: var(--serif); font-weight: 400; font-size: 16px; color: #f0e4c4; margin-bottom: 4px; letter-spacing: 0.03em; }
.card p { font-size: 10px; line-height: 1.55; color: var(--cream-dim); }
---
.skill-node p { font-size: 8px; line-height: 1.45; color: var(--cream-dim); margin-top: 4px; }
.skill-node .req { font-size: 7px; color: #c47f63; margin-top: 3px; letter-spacing: 0.04em; }
.skill-node .buy { position: absolute; top: 7px; right: 7px; width: 15px; height: 15px; border-radius: 50%; background: rgba(143,180,92,0.2); border: 1px solid rgba(143,180,92,0.5); color: #c6e89a; font-size: 11px; line-height: 13px; text-align: center; }
.skill-node.owned .buy { display: none; }
.skill-node .connector { position: absolute; left: 50%; top: -7px; width: 1px; height: 7px; background: rgba(232,213,170,0.16); }
.skill-node:first-child .connector { display: none; }
.skill-node .node-key { font-size: 7px; color: var(--gold); opacity: 0.7; }

/* Quests */
.quest-board { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.quest-card { border: 1px solid rgba(232,213,170,0.13); border-radius: 8px; padding: 14px 15px; background: rgba(255,255,255,0.025); position: relative; overflow: hidden; }
.quest-card.done { border-color: rgba(143,180,92,0.35); background: rgba(143,180,92,0.06); }
.quest-card.locked { opacity: 0.45; }
.quest-card .q-kicker { font-size: 7px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--gold); margin-bottom: 5px; }
.quest-card h4 { font-family: var(--serif); font-size: 16px; font-weight: 400; color: #f2e7c9; }
.quest-card .giver { font-size: 8px; color: var(--cream-dim); font-style: italic; margin-top: 2px; }
.quest-card p.desc { font-size: 9px; line-height: 1.5; color: var(--cream-dim); margin-top: 8px; }
.quest-card .obj { margin-top: 9px; font-size: 9px; color: #ded1b1; }
.quest-card .obj-line { display: flex; justify-content: space-between; gap: 10px; padding: 3px 0; }
.quest-card .obj-line em { font-style: normal; color: var(--gold); }
.quest-card .reward { display: flex; gap: 12px; margin-top: 10px; padding-top: 8px; border-top: 1px solid rgba(255,255,255,0.07); font-size: 9px; color: var(--cream-dim); }
.quest-card .reward b { color: var(--gold-bright); font-weight: 600; }
.quest-card .q-status { position: absolute; top: 12px; right: 12px; font-size: 8px; letter-spacing: 0.1em; text-transform: uppercase; color: #a7cb75; }
.daily-wrap { margin-top: 22px; }
.daily-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.daily-card { border: 1px solid rgba(232,213,170,0.12); border-radius: 8px; padding: 13px; background: rgba(255,255,255,0.025); }
.daily-card.complete { border-color: rgba(217,181,103,0.45); background: rgba(217,181,103,0.07); }
.daily-card h4 { font-family: var(--serif); font-size: 14px; font-weight: 400; color: #f0e4c5; }
.daily-card p { font-size: 9px; color: var(--cream-dim); margin-top: 3px; line-height: 1.4; }
.daily-card .d-prog { height: 4px; background: rgba(255,255,255,0.08); border-radius: 2px; overflow: hidden; margin-top: 10px; }
.daily-card .d-prog i { display: block; height: 100%; background: linear-gradient(90deg, #b39455, #ecd18b); }
.daily-card .d-foot { display: flex; justify-content: space-between; margin-top: 7px; font-size: 8px; color: var(--cream-dim); }
.daily-card .d-foot b { color: var(--gold); }

/* Journal */
.journal-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 10px; }
.entry { display: flex; gap: 11px; padding: 12px; border-radius: 8px; border: 1px solid rgba(232,213,170,0.11); background: rgba(255,255,255,0.025); }
.entry.unknown { opacity: 0.4; }
.entry .e-ico { width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex: 0 0 auto; font-size: 16px; background: rgba(0,0,0,0.3); border: 1px solid var(--e-color, rgba(232,213,170,0.2)); color: var(--e-color, var(--gold)); text-shadow: 0 0 10px var(--e-color, transparent); }
.entry b { display: block; font-size: 11px; color: #f0e4c4; }
.entry small { display: block; font-size: 8px; color: var(--cream-dim); margin-top: 2px; letter-spacing: 0.04em; }
.entry p { font-size: 8px; line-height: 1.4; color: rgba(205,191,158,0.7); margin-top: 4px; }
.entry .count { margin-left: auto; font-family: var(--serif); font-size: 16px; color: var(--gold-bright); flex: 0 0 auto; }
.landmark-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px,1fr)); gap: 8px; margin-top: 12px; }
.landmark { display: flex; gap: 10px; align-items: center; padding: 9px 11px; border-radius: 7px; border: 1px solid rgba(232,213,170,0.1); background: rgba(255,255,255,0.02); font-size: 10px; color: #e8dcc0; }
.landmark.unknown { opacity: 0.35; font-style: italic; }
.landmark .l-ico { width: 22px; text-align: center; color: var(--gold); font-size: 13px; }
.landmark small { margin-left: auto; font-size: 7px; color: var(--cream-dim); letter-spacing: 0.08em; text-transform: uppercase; }

/* Achievements */
.ach-list { display: flex; flex-direction: column; gap: 7px; }
.ach { display: flex; align-items: center; gap: 13px; padding: 11px 14px; border-radius: 8px; border: 1px solid rgba(232,213,170,0.11); background: rgba(255,255,255,0.022); }
.ach.done { border-color: rgba(143,180,92,0.32); background: rgba(143,180,92,0.05); }
.ach .a-ico { width: 34px; height: 34px; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex: 0 0 auto; background: rgba(0,0,0,0.3); border: 1px solid rgba(217,181,103,0.25); color: var(--gold-bright); font-size: 15px; }
.ach.done .a-ico { border-color: rgba(143,180,92,0.5); color: #c7e896; }
.ach .a-body { flex: 1; min-width: 0; }
.ach b { display: block; font-size: 11px; color: #f0e4c4; }
.ach p { font-size: 8px; color: var(--cream-dim); margin-top: 2px; }
.ach .a-prog { width: 130px; flex: 0 0 auto; }
.ach .a-prog .mini { height: 4px; border-radius: 2px; background: rgba(255,255,255,0.08); overflow: hidden; }
.ach .a-prog .mini i { display: block; height: 100%; background: linear-gradient(90deg, #8fa85c, #d1e394); }
.ach .a-prog span { display: block; text-align: right; font-size: 7px; color: var(--cream-dim); margin-top: 3px; }
.ach .a-reward { font-size: 8px; color: var(--gold); text-align: right; width: 96px; flex: 0 0 auto; line-height: 1.5; }
.ach .a-reward b { display: inline; color: var(--gold-bright); }

/* Map */
.map-panel { display: grid; grid-template-columns: 1.5fr 0.5fr; gap: 18px; }
#world-map { width: 100%; aspect-ratio: 1; border-radius: 8px; border: 1px solid rgba(232,213,170,0.18); background: #1d2617; }
.map-legend { display: flex; flex-direction: column; gap: 8px; font-size: 9px; color: var(--cream-dim); }
.map-legend div { display: flex; align-items: center; gap: 7px; }
.map-legend i { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
.map-note { margin-top: 12px; font-size: 8px; line-height: 1.5; color: rgba(205,191,158,0.6); font-style: italic; }

/* Settings */
.settings-list { display: flex; flex-direction: column; gap: 2px; max-width: 660px; }
.setting { display: flex; align-items: center; gap: 16px; padding: 14px 4px; border-bottom: 1px solid rgba(232,213,170,0.08); }
.setting label { flex: 1; font-size: 11px; color: #ebdfc0; }
.setting label small { display: block; font-size: 8px; color: var(--cream-dim); margin-top: 2px; }
.setting input[type="range"] { width: 180px; accent-color: #c7a85f; }
.setting .toggle { width: 44px; height: 23px; border-radius: 999px; background: rgba(255,255,255,0.12); position: relative; transition: background 0.2s; flex: 0 0 auto; }
.setting .toggle::after { content: ''; position: absolute; top: 3px; left: 3px; width: 17px; height: 17px; border-radius: 50%; background: #d8cba8; transition: transform 0.2s; }
.setting .toggle.on { background: rgba(143,180,92,0.55); }
.setting .toggle.on::after { transform: translateX(21px); background: #f2e6c7; }
.setting .value { width: 42px; text-align: right; font-size: 10px; color: var(--gold); }
.danger-btn { padding: 9px 16px; border-radius: 5px; border: 1px solid rgba(211,91,57,0.4); color: #e59a80; font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase; }
.danger-btn:hover { background: rgba(211,91,57,0.12); }
.controls-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 4px 24px; margin-top: 14px; font-size: 10px; color: var(--cream-dim); }
.controls-grid div { display: flex; justify-content: space-between; padding: 5px 0; border-bottom: 1px solid rgba(255,255,255,0.04); }
.controls-grid b { color: #e8dcc0; font-weight: 500; }

/* ---------- Death ---------- */
#death-screen { z-index: 45; background: radial-gradient(ellipse at center, rgba(45,20,14,0.55), rgba(5,6,4,0.92)); backdrop-filter: blur(6px); }
.death-card { text-align: center; max-width: 440px; padding: 30px; }
.death-card small { font-size: 8px; letter-spacing: 0.34em; color: #c98567; }
.death-card h2 { font-family: var(--serif); font-size: clamp(32px, 5vw, 48px); font-weight: 400; color: #f4e6c6; margin: 8px 0 10px; }
.death-card p { font-size: 11px; line-height: 1.65; color: var(--cream-dim); margin-bottom: 22px; }

/* ---------- Touch ---------- */
#touch-controls { position: absolute; inset: 0; z-index: 20; pointer-events: none; }
#touch-controls > * { pointer-events: auto; }
.joystick {
  position: absolute; left: calc(24px + var(--safe-left)); bottom: calc(26px + var(--safe-bottom));
  width: 122px; height: 122px; border-radius: 50%;
  background: radial-gradient(circle, rgba(25,33,20,0.5), rgba(12,16,9,0.36));
  border: 1px solid rgba(232,213,170,0.2); box-shadow: 0 0 0 10px rgba(20,27,15,0.12);
  touch-action: none;
}
#joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; border-radius: 50%;
  transform: translate(-50%,-50%);
  background: radial-gradient(circle at 40% 35%, rgba(240,220,170,0.65), rgba(160,135,80,0.35));
  border: 1px solid rgba(255,240,200,0.35); box-shadow: 0 4px 14px rgba(0,0,0,0.35);
}
.touch-actions {
  position: absolute; right: calc(16px + var(--safe-right)); bottom: calc(24px + var(--safe-bottom));
  width: 196px; height: 196px;
}
.tbtn {
  position: absolute; width: 50px; height: 50px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: radial-gradient(circle at 40% 32%, rgba(57,72,42,0.9), rgba(19,25,14,0.86));
  border: 1px solid rgba(232,213,170,0.3); color: #eadcba;
  font-size: 12px; font-weight: 800; box-shadow: 0 5px 18px rgba(0,0,0,0.35);
  touch-action: none;
}
.tbtn:active { transform: scale(0.94); background: rgba(217,181,103,0.24); }
.tbtn.locked { opacity: 0.3; }
.tbtn.biggest { width: 66px; height: 66px; right: 2px; bottom: 4px; font-size: 15px; background: radial-gradient(circle at 40% 32%, rgba(114,77,45,0.95), rgba(41,25,14,0.92)); border-color: rgba(240,200,130,0.42); }
.tbtn.big { width: 56px; height: 56px; right: 74px; bottom: 10px; }
.tbtn[data-touch="sniff"] { right: 2px; bottom: 80px; }
.tbtn[data-touch="dig"] { right: 74px; bottom: 74px; }
.tbtn[data-touch="jump"] { right: 132px; bottom: 26px; }
.tbtn[data-touch="stomp"] { right: 2px; bottom: 140px; width: 42px; height: 42px; }
.tbtn[data-touch="guard"] { right: 54px; bottom: 140px; width: 42px; height: 42px; }
.tbtn[data-touch="rush"] { right: 106px; bottom: 118px; width: 42px; height: 42px; }
.tbtn[data-touch="rage"] { right: 150px; bottom: 72px; width: 42px; height: 42px; }
#touch-pause { position: absolute; right: calc(18px + var(--safe-right)); top: calc(16px + var(--safe-top)); width: 40px; height: 38px; border-radius: 8px; }

/* ---------- Intro cinematic ---------- */
#intro-cinematic {
  position: absolute; inset: 0; z-index: 18; display: flex; align-items: flex-end; justify-content: center;
  padding-bottom: 18vh; pointer-events: none;
  background: linear-gradient(180deg, transparent 50%, rgba(5,8,4,0.7) 100%);
  animation: introbg 6.5s ease both;
}
.intro-line { text-align: center; animation: introtext 6.5s ease both; }
.intro-line small { font-size: 8px; letter-spacing: 0.4em; color: var(--gold); }
.intro-line p { font-family: var(--serif); font-size: clamp(18px, 2.6vw, 26px); line-height: 1.5; color: #f2e6c7; margin-top: 10px; text-shadow: 0 4px 24px rgba(0,0,0,0.8); }
@keyframes introbg { 0%, 80% { opacity: 1; } 100% { opacity: 0; } }
@keyframes introtext { 0% { opacity: 0; transform: translateY(14px); } 14%, 74% { opacity: 1; transform: none; } 100% { opacity: 0; transform: translateY(-6px); } }

/* ---------- Responsive ---------- */
@media (max-width: 900px) {
  .stat-panel { width: 280px; }
  .stat-head span { display: none; }
  #quest-tracker { width: 232px; }
  #minimap-wrap { width: 142px; height: 142px; }
  #toasts { top: calc(232px + var(--safe-top)); width: 240px; }
  .panel-grid { grid-template-columns: 1fr; }
  .skills-grid { grid-template-columns: repeat(3, 1fr); }
  .map-panel { grid-template-columns: 1fr; }
  .pause-inner { height: 92vh; }
  .pause-head { padding: 16px 18px 12px; }
  .pause-title h2 { font-size: 26px; }
  .menu-content { padding: 18px; }
  .quest-board { grid-template-columns: 1fr; }
  .daily-grid { grid-template-columns: 1fr; }
}
@media (max-width: 640px) {
  .title-inner { padding-top: 10vh; }
  .title-features { gap: 16px; }
  .title-features span { font-size: 7px; }
  .title-corner { display: none; }
  .tagline br { display: none; }
  .title-foot { font-size: 9px; }
  .title-foot .tiny { font-size: 8px; }
  .hud-top { top: calc(10px + var(--safe-top)); left: calc(10px + var(--safe-left)); right: calc(10px + var(--safe-right)); gap: 8px; }
  .stat-panel { width: 218px; padding: 9px 10px 8px 9px; gap: 8px; }
  .level-badge { width: 42px; height: 48px; }
  .level-badge span { font-size: 21px; }
  .stat-head b { font-size: 12px; }
  .bar { height: 9px; }
  .bar.stamina { height: 7px; }
  .bar.rage { height: 6px; }
  .bar span { font-size: 6px; }
  .resource-panel { gap: 7px; padding: 7px 8px; }
  .res { font-size: 10px; gap: 3px; }
  .res-ico { font-size: 10px; }
  .icon-btn { width: 27px; height: 27px; font-size: 12px; }
  .center-top { position: absolute; top: 58px; left: 50%; transform: translateX(-50%); }
  .clock { padding: 5px 12px; font-size: 9px; }
  .clock small { display: none; }
  #boss-wrap { width: 74vw; position: fixed; top: calc(78px + var(--safe-top)); left: 50%; transform: translateX(-50%); }
  #quest-tracker { left: calc(10px + var(--safe-left)); top: calc(88px + var(--safe-top)); width: 190px; padding: 8px 10px 7px; }
  .quest-row b { font-size: 9px; }
  .quest-row span { font-size: 8px; }
  #minimap-wrap { width: 108px; height: 108px; top: calc(58px + var(--safe-top)); right: calc(10px + var(--safe-right)); }
  .compass.n { font-size: 8px; }
  #toasts { top: calc(180px + var(--safe-top)); right: calc(10px + var(--safe-right)); width: 210px; }
  .toast { padding: 8px 9px; }
  .toast b { font-size: 10px; }
  .toast span { font-size: 8px; }
  #hotbar { display: none; }
  #hint-bar { display: none; }
  #interaction { bottom: calc(158px + var(--safe-bottom)); min-width: 170px; padding: 8px 14px; }
  #ability-hint { bottom: calc(150px + var(--safe-bottom)); }
  .region-popup { padding: 12px 26px 14px; min-width: 260px; }
  #region-popup b { font-size: 22px; }
  #region-popup span { font-size: 9px; text-align: center; }
  .pause-inner { width: 100vw; height: 100vh; border-radius: 0; border: 0; }
  .pause-head { flex-wrap: wrap; gap: 10px; }
  .pause-res { margin-left: 0; order: 3; width: 100%; justify-content: space-between; }
  .pause-title h2 { font-size: 24px; }
  .tabs { padding: 0 10px; }
  .tabs button { padding: 12px 12px; font-size: 9px; }
  .menu-content { padding: 14px 12px 24px; }
  .skills-grid { grid-template-columns: 1fr; }
  .skill-node p { font-size: 9px; }
  .cosmetics { grid-template-columns: 1fr; }
  .ach { flex-wrap: wrap; gap: 8px; }
  .ach .a-prog { width: 100%; }
  .ach .a-reward { width: auto; margin-left: auto; }
  .ach-list { gap: 6px; }
  .controls-grid { grid-template-columns: 1fr; }
  .journal-grid { grid-template-columns: 1fr; }
  .daily-grid { grid-template-columns: 1fr; }
  .title-actions .btn { padding: 13px 26px; }
  .death-card { padding: 20px; }
}
@media (max-height: 620px) and (orientation: landscape) {
  .title-inner { transform: scale(0.82); }
  .title-features { margin-top: 18px; padding-top: 14px; }
  .tagline { margin-top: 12px; }
  .title-actions { margin-top: 16px; }
  .title-foot { margin-top: 12px; }
  #quest-tracker { display: none; }
  #minimap-wrap { width: 112px; height: 112px; }
