+      hitAny = true;
+      const crit = Math.random() < stats.critChance;
+      let dmg = stats.attack * (crit ? 1.65 : 1) * (this.buffs.damage > 0 ? 1.25 : 1);
+      if (this.buffs.rage > 0) dmg *= 1.4;
