+    this.effects.burst(this.boar.pos.x, this.boar.pos.y + 0.8, this.boar.pos.z, 42, {
+      spread: 2.4, up: 4, size: 1.2, r: 1, g: 0.35, b: 0.18, life: 1.2, gravity: 1.2,
